'use strict';
const $=s=>document.querySelector(s), C=Core, icon=name=>Icons.render(name);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=0)=>n==null?'–':Number(n).toLocaleString('de-AT',{maximumFractionDigits:d,minimumFractionDigits:d});
const pct=n=>n==null?'–':fmt(n*100)+' %';
const date=t=>t?new Date(t).toLocaleString('de-AT',{dateStyle:'short',timeStyle:'short'}):'Noch nicht geprüft';
const duration=ms=>{const s=Math.floor((ms||0)/1000);return Math.floor(s/60)+':'+String(s%60).padStart(2,'0');};
const native=typeof Native!=='undefined',web=typeof WebFeatures!=='undefined',bridge=native?Native:web?WebFeatures:null;
let state={schema:1,settings:{modules:[1,3],goal:30,dark:false,theme:'green',largeText:false,reduceMotion:false,keepAwake:true,haptics:true,sessionSize:20,auto:true,sourceEnabled:false},attempts:[],sessions:[],bookmarks:[],active:null};
try{const saved=JSON.parse(bridge?bridge.loadState():localStorage.getItem('fahrklar')||'{}');if(saved.schema===1)state={...state,...saved,settings:{...state.settings,...saved.settings}};}catch(e){}
let catalog=[],meta={},route='home',filter='all',topic='',search='',selected=[],feedback=false,paused=false,tickStart=0,tickMs=0,statPeriod=0,statModule=0,historyFilter='all',historyLimit=30,reviewId=null,importPending=null,saveFailed=false;
let pmap=new Map();
let aiReady=false,aiPending=null,aiSequence=0,aiTest={phase:'idle',message:''};const aiCache=new Map();
try{aiReady=!!bridge?.hasGeminiKey?.();}catch(e){}
let updateState={phase:'idle',message:'',available:false},appInfo={version:'Vorschau',stable:false};
try{if(bridge?.appInfo)appInfo=JSON.parse(bridge.appInfo());}catch(e){}
let transferBusy=false,downloadState={phase:'idle',message:''};
function rebuildProgress(){pmap=new Map();for(const a of state.attempts){if(a.skipped)continue;const k=a.id+':'+a.version;const p=pmap.get(k)||{seen:false,streak:0,wrong:0};p.seen=true;p.streak=a.correct?p.streak+1:0;p.wrong+=a.correct?0:1;p.last=a;p.mastered=p.streak>=3;pmap.set(k,p);}}
function progress(q){return pmap.get(q.id+':'+q.version)||{seen:false,mastered:false,streak:0,wrong:0};}
function save(){const s=JSON.stringify(state);try{if(bridge){if(!bridge.saveState(s))throw Error('Speicher voll');}else localStorage.setItem('fahrklar',s);saveFailed=false;}catch(e){saveFailed=true;toast('Speichern fehlgeschlagen. Bitte eine Sicherung exportieren und Speicherplatz freigeben.',true);}}
function toast(message,sticky=false){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);if(!sticky)toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),6000);}
function ask(text,accept='Bestätigen'){return new Promise(resolve=>{const d=document.createElement('dialog');d.className='card';d.style.maxWidth='420px';d.innerHTML=`<p>${esc(text)}</p><div class="row"><button data-no>Abbrechen</button><button class="primary" data-yes>${esc(accept)}</button></div>`;document.body.append(d);const end=v=>{d.close();d.remove();resolve(v);};d.querySelector('[data-yes]').onclick=()=>end(true);d.querySelector('[data-no]').onclick=()=>end(false);d.oncancel=e=>{e.preventDefault();end(false);};d.showModal();});}
async function loadCatalog(){if(web&&!state.settings.sourceEnabled){catalog=[];meta={};rebuildProgress();return;}try{const r=await fetch('catalog.json',{cache:'no-store'});if(!r.ok)throw Error('Katalog fehlt');const data=await r.json();catalog=C.normalize(data.questions||[]);meta=data.meta||{};}catch(e){if(native)toast('Gespeicherter Katalog konnte nicht geladen werden. Bitte erneut aktualisieren.');}rebuildProgress();}
function currentPool(){return catalog.filter(q=>q.classes.some(c=>state.settings.modules.includes(c)));}
function empty(title,body){return `<div class="card empty"><span class="empty-icon">${icon('book-open')}</span><h2>${esc(title)}</h2><p class="muted">${esc(body)}</p></div>`;}
function stat(value,label,symbol='↗'){return `<div class="card stat"><span class="symbol">${icon(symbol)}</span><strong>${value}</strong><small>${esc(label)}</small></div>`;}
function nav(){const links=[['home','house','Pfad'],['learn','book-open','Üben'],['exam','timer','Prüfung'],['stats','chart-no-axes-combined','Fortschritt'],['history','refresh-cw','Verlauf']];$('#nav').innerHTML=links.map(([r,i,l])=>`<button data-route="${r}" class="${route===r?'active':''}" ${route===r?'aria-current="page"':''}><span class="navicon" aria-hidden="true">${icon(i)}</span>${l}</button>`).join('');$('#nav').hidden=route==='session';}
function render(){document.body.classList.toggle('dark',state.settings.dark);document.body.classList.toggle('text-large',state.settings.largeText);document.body.classList.toggle('motion-reduced',state.settings.reduceMotion);for(const name of ['green','blue','purple','orange'])document.body.classList.toggle('theme-'+name,state.settings.theme===name);if(bridge?.setKeepAwake)try{bridge.setKeepAwake(!!state.settings.keepAwake&&route==='session'&&!!state.active&&!paused);}catch(e){}nav();const renderers={home:playfulHome,learn,exam,stats,history,settings:cleanSettings,session,review},root=$('#app');root.classList.remove('route-home','route-learn','route-exam','route-stats','route-history','route-settings','route-session','route-review','view-enter');root.classList.add('route-'+route);root.innerHTML=(renderers[route]||playfulHome)();void root.offsetWidth;root.classList.add('view-enter');attachImageErrors();}
async function go(r){if(route==='session'&&r!=='session'&&state.active){if(!await ask('Lerneinheit beenden? Deine bisherigen Antworten bleiben im Verlauf gespeichert.','Beenden'))return;finish('aborted',false);}route=r;render();window.scrollTo(0,0);}


function aiQuestionKey(q){return q.id+':'+q.version;}
function findAiQuestion(key){
  if(state.active?.mode==='exam')return null;
  if(route==='session'&&feedback&&state.active?.mode==='train'){const q=question();return aiQuestionKey(q)===key?q:null;}
  if(route==='review')return state.sessions.find(s=>s.id===reviewId)?.attempts.find(q=>aiQuestionKey(q)===key)||null;
  return null;
}
function aiContent(key){
  const cached=aiCache.get(key),waiting=aiPending?.key===key;
  return `<h3>${icon('sparkles')} Einfach erklärt</h3>${cached?.text?'<div class="ai-explanation">'+esc(cached.text)+'</div>':''}${cached?.error?'<p class="notice" role="alert">'+esc(cached.error)+'</p>':''}${waiting?'<p role="status">Gemini erstellt deine Erklärung …</p>':''}${!aiReady?'<p class="muted tiny">Hinterlege deinen eigenen Gemini-API-Key, um kurze Erklärungen und Merksätze zu erhalten.</p><button class="secondary full" data-action="ai-setup">Gemini einrichten</button>':cached?.text?'':`<button class="secondary full" data-ai-key="${esc(key)}" ${aiPending?'disabled':''}>${icon('sparkles')} ${waiting?'Erklärung wird geladen …':cached?.error?'Erneut versuchen':'Einfach erklären'}</button>`}<p class="tiny muted">KI-Lernhilfe · kann Fehler enthalten. Maßgeblich bleibt die Kataloglösung. Beim Abruf gehen diese Frage, Antworten, Lösung und Bilder an Google; es gilt dein Gemini-Tarif.</p>`;
}
function aiPanel(q){if(state.active?.mode==='exam')return '';const key=aiQuestionKey(q);return `<section class="card ai-card" data-ai-panel="${esc(key)}">${aiContent(key)}</section>`;}
function refreshAiPanels(){document.querySelectorAll('[data-ai-panel]').forEach(el=>el.innerHTML=aiContent(el.dataset.aiPanel));}
function requestAi(key){
  const q=findAiQuestion(key);if(!q||aiPending)return;
  if(!bridge){toast('Gemini ist hier nicht verfügbar.');return;}
  if(!aiReady){bridge.configureGemini();return;}
  if(aiCache.get(key)?.text)return;
  const id=String(++aiSequence)+':'+key;aiPending={id,key};aiCache.delete(key);refreshAiPanels();
  // Whitelist the question fields: no attempts, settings, elapsed time or key.
  const payload={text:q.text,image:q.image,answers:q.answers.map(a=>({text:a.text,correct:a.correct,image:a.image}))};
  try{bridge.explainQuestion(id,JSON.stringify(payload));}catch(e){aiPending=null;aiCache.set(key,{error:'KI-Anfrage konnte nicht gestartet werden.'});refreshAiPanels();}
}
function settingToggle(id,title,body,checked){return `<label class="preference-row" for="${id}"><span><strong>${esc(title)}</strong><small>${esc(body)}</small></span><input id="${id}" type="checkbox" ${checked?'checked':''}></label>`;}
function themeSettings(){const themes=[['green','Waldgrün'],['blue','Klarblau'],['purple','Violett'],['orange','Orange']];return `<div class="card theme-card settings-card"><h2>${icon('palette')} Darstellung</h2><p class="muted">Eine ruhige Hauptfarbe für die gesamte Oberfläche.</p><div class="theme-grid" role="radiogroup" aria-label="Farbthema">${themes.map(([value,label])=>`<button data-theme="${value}" class="theme-option ${state.settings.theme===value?'selected':''}" role="radio" aria-checked="${state.settings.theme===value}"><span class="theme-preview ${value}"><i></i><i></i><i></i></span><strong>${label}</strong>${state.settings.theme===value?icon('circle-check'):''}</button>`).join('')}</div><div class="preference-list">${settingToggle('dark','Dunkles Design','Angenehmer bei wenig Licht.',state.settings.dark)}${settingToggle('largeText','Größere Schrift','Fragen und Bedienelemente besser lesbar.',state.settings.largeText)}${settingToggle('reduceMotion','Animationen reduzieren','Deaktiviert Übergänge und Belohnungsbewegungen.',state.settings.reduceMotion)}</div></div>`;}
function aiSettings(){const testing=aiTest.phase==='loading',status=aiTest.message?`<p class="ai-test-status ${aiTest.phase==='success'?'success':aiTest.phase==='error'?'notice':''}" role="${aiTest.phase==='error'?'alert':'status'}">${aiTest.phase==='success'?icon('circle-check'):aiTest.phase==='error'?icon('circle-x'):''}${esc(aiTest.message)}</p>`:'';const storage=web?'Dein Key bleibt nur für diese Browser-Sitzung gespeichert und wird beim Schließen des Browsers entfernt.':'Dein Key bleibt verschlüsselt auf diesem Gerät.';return `<div class="card ai-settings-card settings-card"><h2>${icon('sparkles')} KI-Lernhilfe</h2><p class="muted">Gemini erklärt dir nach einer Antwort kurz die Lösung und gibt dir einen Merksatz. Während einer Prüfungssimulation sind Erklärungen gesperrt.</p><span class="pill ${aiReady?'good':''}">${aiReady?'API-Key hinterlegt':'Noch nicht eingerichtet'}</span><button class="secondary full" data-action="ai-setup">${aiReady?'API-Key ändern':'Gemini einrichten'}</button>${aiReady?`<button class="secondary full" data-action="ai-test" ${testing?'disabled':''}>${icon('wifi')} ${testing?'Verbindung wird geprüft …':'Gemini-Verbindung testen'}</button>${status}<button class="text-btn full" data-action="ai-remove">API-Key entfernen</button>`:''}<p class="tiny muted">${storage} Füge ausschließlich einen API-Key aus Google AI Studio ein – keine JSON-Datei und keinen OAuth-Token.</p></div>`;}
function learningSettings(){const sizes=[[10,'Kurz'],[20,'Normal'],[30,'Intensiv']];return `<div class="card settings-card"><h2>${icon('book-open')} Lernen</h2><h3>Meine Module</h3>${moduleChips()}<p class="tiny muted">A1/A2 lernen mit Modul A. BE bleibt deaktiviert, solange die Quelle keinen separaten BE-Fragensatz liefert.</p><label for="goal">Tagesziel</label><div class="input-suffix"><input id="goal" type="number" min="1" max="1000" value="${state.settings.goal}"><span>Fragen</span></div><label>Länge einer Lernrunde</label><div class="choice-grid" role="radiogroup" aria-label="Länge einer Lernrunde">${sizes.map(([n,label])=>`<button data-session-size="${n}" class="${state.settings.sessionSize===n?'selected':''}" role="radio" aria-checked="${state.settings.sessionSize===n}"><strong>${n}</strong><small>${label}</small></button>`).join('')}</div><div class="preference-list">${settingToggle('keepAwake','Bildschirm beim Lernen aktiv halten','Verhindert das Ausschalten während einer laufenden Einheit.',state.settings.keepAwake)}${settingToggle('haptics','Haptisches Feedback','Kurze Rückmeldung nach einer Antwort.',state.settings.haptics)}${settingToggle('auto','Fragen täglich automatisch prüfen','Höchstens einmal pro Tag beim Öffnen.',state.settings.auto)}</div></div>`;}
function cleanSettings(){const moduleNames=state.settings.modules.map(n=>C.classes[n]||n).join(' · ');return `<span class="eyebrow">EINSTELLUNGEN</span><h1>Alles an einem Ort.</h1><div class="settings-overview"><span>${icon('book-open')} ${esc(moduleNames)}</span><span>${state.settings.sessionSize} Fragen</span><span>${state.settings.dark?'Dunkel':'Hell'}</span><span>${esc(appInfo.version)}</span></div><h2 class="settings-heading">Persönlich</h2>${themeSettings()}${learningSettings()}<h2 class="settings-heading">Dienste</h2>${aiSettings()}${updateCard()}${sourceCard()}<details class="card settings-section"><summary>${icon('download')} Offline-Bilder</summary><p class="muted">Fragetexte und Antworten bleiben gespeichert. Lade die Bilder deiner gewählten Module vor einer Offline-Lernrunde herunter.</p><button class="secondary full" data-action="images" ${!catalog.length||transferBusy?'disabled':''}>${icon('download')} Bilder meiner Module herunterladen</button><p class="tiny muted">Der erste Download kann einige Minuten dauern. Fehlende Bilder werden beim nächsten Mal erneut versucht.</p></details><h2 class="settings-heading">Daten & Info</h2><details class="card settings-section"><summary>${icon('shield-check')} Sicherung und Datenschutz</summary><p class="muted">Ohne Konto, Werbung oder Analyse-Tracking. Lernstände und Verlauf bleiben auf diesem Gerät.</p><button class="secondary full" data-action="export">Sicherung als JSON exportieren</button><button class="text-btn full" data-action="import">Sicherung wiederherstellen</button><button class="text-btn full danger" data-action="reset">Lernfortschritt löschen</button></details><details class="card settings-section"><summary>Quelle & Hinweise</summary><p>Unabhängige Lern-App. Nicht mit F-Online oder einer Behörde verbunden. F-Online verlangt laut AGB eine schriftliche Genehmigung zur Weiterverwendung. Kläre diese mit info@f-online.at.</p><p>Die APK enthält keine fremden Fragen oder Bilder. Downloads gehen direkt an F-Online; Lernstatistiken werden nicht übertragen.</p><button class="text-btn" data-action="source">Fragenquelle öffnen ${icon('external-link')}</button><p class="tiny muted">Fahrklar 1.0 · Österreich · Deutsch</p></details><details class="card settings-section"><summary>Open-Source-Lizenzen</summary><p>Piktogramme: Lucide unter ISC-Lizenz; einzelne Formen stammen aus Feather (MIT).</p><pre class="license-text">${esc(Icons.license)}</pre></details>`;}

function topicPicker(){
  const opener=document.activeElement,d=document.createElement('dialog');
  d.className='topic-dialog';d.setAttribute('aria-labelledby','topic-title');
  d.innerHTML=`<div class="picker-head"><div class="row"><h2 id="topic-title">Thema auswählen</h2><button class="text-btn" data-close>Schließen</button></div><label for="topic-search">Themen durchsuchen</label><input id="topic-search" type="search" placeholder="z. B. Bremsen oder Anhänger" autocomplete="off"></div><div class="picker-results"></div>`;
  const qs=currentPool(),results=d.querySelector('.picker-results');
  function draw(query=''){
    const groups=C.topicGroups(qs,query);
    results.innerHTML=`<button class="topic-option ${!topic?'selected':''}" data-topic="" aria-pressed="${!topic}"><span>Alle Themen<small>${fmt(qs.length)} Fragen in deinen Modulen</small></span>${!topic?icon('circle-check'):''}</button>`+groups.map(g=>`<details class="topic-group" ${query||g.items.some(i=>i.value===topic)?'open':''}><summary>${esc(g.name)}<small>${g.items.length} Themen · ${fmt(g.items.reduce((n,i)=>n+i.count,0))} Fragen</small></summary>${g.items.map(i=>`<button class="topic-option ${topic===i.value?'selected':''}" data-topic="${esc(i.value)}" aria-pressed="${topic===i.value}"><span>${esc(i.label)}<small>${fmt(i.count)} Fragen</small></span>${topic===i.value?icon('circle-check'):''}</button>`).join('')}</details>`).join('')+(!groups.length?'<p class="muted">Kein Thema gefunden. Versuche einen anderen Suchbegriff.</p>':'');
  }
  const close=()=>{d.close();d.remove();if(opener?.isConnected)opener.focus();};
  d.querySelector('[data-close]').onclick=close;d.oncancel=e=>{e.preventDefault();close();};
  d.querySelector('#topic-search').oninput=e=>draw(e.target.value.trim());
  results.onclick=e=>{const b=e.target.closest('[data-topic]');if(!b)return;topic=b.dataset.topic;close();render();document.querySelector('[data-action="topics"]')?.focus();};
  document.body.append(d);draw();d.showModal();d.querySelector('#topic-search').focus();
}
function reviewCard(){const qs=currentPool(),due=qs.filter(q=>C.reviewStatus(progress(q)).due),wrong=due.filter(q=>!progress(q).last.correct);return `<div class="card"><div class="row"><h2>Dein Wiederholungsplan</h2><span class="pill">${due.length} fällig</span></div><p class="muted">${due.length?wrong.length+' zuletzt falsch beantwortete Fragen warten auf dich.':'Für den Moment ist nichts fällig. Deine nächste Lernrunde mischt neue Fragen und Auffrischungen.'}</p><button class="secondary full" data-action="review-due" ${!due.length?'disabled':''}>${icon('refresh-cw')} Fällige Fragen üben</button><p class="tiny muted">Falsch: nach 10 Minuten wiederholen. Richtig: nach 1, 3, 7, 14 und schließlich 30 Tagen. In Lernrunden erscheint eine falsche Frage zusätzlich einmal nach einigen anderen Fragen, spätestens am Ende.</p></div>`;}
function updateCard(){if(web)return `<div class="card"><h2>Web-App aktualisieren</h2><p class="muted">Installiert: ${esc(appInfo.version)}</p><p role="status">${esc(updateState.message||'Neue Versionen werden im Hintergrund vorbereitet.')}</p><button class="secondary full" data-action="check-update" ${updateState.phase==='loading'?'disabled':''}>${icon('refresh-cw')} ${updateState.phase==='loading'?'Version wird geprüft …':'Jetzt nach Aktualisierung suchen'}</button><p class="tiny muted">Beim nächsten Öffnen wird die aktuelle Version verwendet. Dein Lernstand bleibt in diesem Browser gespeichert.</p></div>`;return `<div class="card"><h2>App aktualisieren</h2><p class="muted">Installiert: ${esc(appInfo.version)}</p><p role="status">${esc(updateState.message||'Prüfe, ob eine neue Version auf GitHub verfügbar ist.')}</p><button class="secondary full" data-action="check-update" ${updateState.phase==='loading'?'disabled':''}>${icon('refresh-cw')} ${updateState.phase==='loading'?'Version wird geprüft …':'Nach App-Update suchen'}</button>${updateState.available?'<button class="primary full" data-action="open-update">'+icon('download')+' Update auf GitHub öffnen</button>':''}<p class="tiny muted">${appInfo.stable?'Updates mit demselben Signierschlüssel erhalten deinen Lernstand. Lade die APK herunter und bestätige die Installation in Android.':'Diese Testversion hat noch keine dauerhafte Signatur. Vor einem Versionswechsel eine Sicherung exportieren; Android kann eine Neuinstallation verlangen.'}</p><p class="tiny muted">Die manuelle Prüfung verbindet sich mit GitHub. Fragenkatalog und App werden getrennt aktualisiert.</p></div>`;}

function sourceCard(){const age=Date.now()-(meta.checkedAt||0),loading=downloadState.phase==='loading',failed=downloadState.phase==='error';return `<div class="card download-card" aria-busy="${loading}"><div class="row"><h3>Dein Fragenkatalog</h3><span class="pill ${catalog.length&&age<86400000?'good':''}">${catalog.length?fmt(catalog.length)+' Fragen':'Noch nicht geladen'}</span></div><p class="muted tiny">${catalog.length?'Letzter erfolgreicher Abgleich: '+date(meta.checkedAt):'Ein Internetzugang ist nur zum Herunterladen und Aktualisieren nötig.'}</p>${age>86400000&&catalog.length?'<p class="notice">Der letzte Abgleich liegt länger als einen Tag zurück. Der gespeicherte Stand bleibt nutzbar.</p>':''}${loading?'<div class="download-status" role="status">'+icon('loader-circle')+'<span>Fragen werden geladen und geprüft …</span></div><progress aria-label="Fragen werden heruntergeladen"></progress>':''}${failed?'<p class="notice" role="alert">'+icon('circle-alert')+' '+esc(downloadState.message)+(catalog.length?' Deine gespeicherten Fragen bleiben nutzbar.':' Prüfe deine Internetverbindung und versuche es erneut.')+'</p>':''}<button class="${catalog.length?'secondary':'primary'} full" data-action="sync" ${transferBusy?'disabled':''}>${icon(failed?'refresh-cw':catalog.length?'refresh-cw':'download')} ${loading?'Download läuft …':transferBusy?'Download bereits aktiv':failed?'Erneut versuchen':catalog.length?'Jetzt aktualisieren':'Fragen herunterladen'}</button></div>`;}
function downloadIntro(){return `<span class="eyebrow">WILLKOMMEN BEI FAHRKLAR</span><div class="welcome-mark">${icon('book-open')}</div><h1>Dein Führerschein.<br>Dein Lerntempo.</h1><p class="muted">Lade zuerst den Fragenkatalog herunter. Danach kannst du lernen und Prüfungssimulationen starten.</p>${sourceCard()}<div class="card"><h2>Einmal laden. Danach offline üben.</h2><p>${icon('database')} Fragetexte und Antworten bleiben auf deinem Handy.</p><p>${icon('shield-check')} Dein Fortschritt und deine Statistiken werden lokal gespeichert.</p><p class="muted tiny">Für vollständiges Offline-Lernen lade anschließend auch die Bilder deiner Module in den Einstellungen herunter.</p></div><div class="card"><h2>Was möchtest du lernen?</h2><p class="muted">Wähle deine Führerscheinklassen. Du kannst sie später ändern.</p>${moduleChips()}</div>`;}
function home(){if(!catalog.length)return downloadIntro();const qs=currentPool(),s=C.stats(state.attempts,state.sessions,qs),coverage=qs.length?qs.filter(q=>progress(q).mastered).length/qs.length:0;return `<div class="row"><span class="eyebrow">DEIN LERNCOCKPIT</span><span class="pill ${saveFailed?'bad':'good'}">${saveFailed?'Speicherfehler':icon('shield-check')+' Lokal gespeichert'}</span></div><h1>Bereit für die<br>nächste Etappe?</h1><p class="muted">${state.settings.modules.map(c=>esc(C.classes[c]||'Modul '+c)).join(' · ')} · Schritt für Schritt sicherer.</p>${state.active?`<div class="card row"><div><h3>Deine Einheit wartet</h3><small>Fortsetzen oder im Verlauf abschließen.</small></div><button class="primary" data-action="resume">Weiter</button></div>`:''}<div class="card hero row"><div><span class="eyebrow" style="color:#d8d0ff">DEIN FORTSCHRITT</span><h2>Dranbleiben lohnt sich.</h2><p class="muted">${fmt(qs.filter(q=>progress(q).mastered).length)} von ${fmt(qs.length)} Fragen sicher gelernt.</p><button data-action="quick" ${!qs.length?'disabled':''}>Lernrunde starten ${icon('arrow-right')}</button></div><div class="ring" style="--pct:${Math.round(coverage*100)}"><div><strong>${fmt(coverage*100)}<span style="font-size:16px">%</span></strong><small>sicher gelernt</small></div></div></div><div class="grid stats-grid">${stat(fmt(s.today),'Fragen heute','▤')}${stat(fmt(s.streak)+' Tage','Aktuelle Lernserie','♧')}${stat(pct(s.accuracy),'Richtige Antworten','✓')}${stat(fmt(s.qpm,1),'Fragen pro aktiver Minute','◷')}</div><div class="dashboard-grid"><div class="card"><div class="row"><h2>Dein Tagesziel</h2><span class="pill">${s.today} / ${state.settings.goal}</span></div><progress max="${state.settings.goal}" value="${Math.min(s.today,state.settings.goal)}"></progress><p class="muted">${s.today>=state.settings.goal?'Geschafft! Dein Tagesziel ist erreicht.':Math.max(0,state.settings.goal-s.today)+' Fragen bis zu deinem Tagesziel.'}</p><button class="text-btn" data-route="settings">Ziel anpassen ${icon('arrow-right')}</button></div>${sourceCard()}</div>${reviewCard()}<h2 class="section-title">Dein nächster Schritt</h2><div class="card row"><div><h3>Fehler gezielt wiederholen</h3><small>Aus Unsicherheit wird Routine.</small></div><button class="secondary" data-action="weak">Üben ${icon('arrow-right')}</button></div><p class="tiny muted">„Sicher gelernt“ bedeutet: dieselbe Fragenversion dreimal hintereinander richtig. Das ist eine Lernhilfe und keine Bestehensgarantie.</p>`;}
function moduleChips(){return `<div class="chips">${Object.entries(C.classes).map(([id,name])=>{const n=catalog.filter(q=>q.classes.includes(+id)).length;return `<button data-module="${id}" class="${state.settings.modules.includes(+id)?'selected':''}" aria-pressed="${state.settings.modules.includes(+id)}" ${catalog.length&&!n?'disabled':''}>${esc(name)}${catalog.length?' · '+n:''}</button>`;}).join('')}<button disabled title="Kein bestätigtes BE-Modul in der Quelle">BE · nicht verfügbar</button></div>`;}
function learn(){if(!catalog.length)return downloadIntro();const qs=currentPool();let results=qs.filter(q=>(!topic||q.topic===topic)&&(!search||(q.text+' '+q.id+' '+q.answers.map(a=>a.text).join(' ')).toLowerCase().includes(search.toLowerCase()))&&(filter==='all'||filter==='due'&&C.reviewStatus(progress(q)).due||filter==='new'&&!progress(q).seen||filter==='wrong'&&progress(q).last&&!progress(q).last.correct||filter==='bookmarked'&&state.bookmarks.includes(q.id)||filter==='mastered'&&progress(q).mastered));return `<span class="eyebrow">DEIN TRAINING</span><h1>Wissen, das bleibt.</h1><p class="muted">Wähle deine Module und übe in deinem Tempo.</p>${moduleChips()}${reviewCard()}<div class="card"><label for="search">Frage oder Nummer suchen</label><input id="search" type="search" placeholder="z. B. Vorrang oder 464" value="${esc(search)}"><label>Themengebiet</label><button class="topic-trigger full" data-action="topics" aria-haspopup="dialog"><span><small>${topic?'Ausgewähltes Thema':'THEMENAUSWAHL'}</small>${esc(topic||'Alle Themen')}</span>${icon('book-open')}</button><div class="chips">${[['all','Alle'],['new','Unbeantwortet'],['wrong','Zuletzt falsch'],['due','Jetzt fällig'],['bookmarked','Merkliste'],['mastered','Sicher']].map(([f,l])=>`<button data-filter="${f}" class="${filter===f?'selected':''}">${l}</button>`).join('')}</div><div class="row"><small>${fmt(results.length)} passende Fragen</small><button class="primary" data-action="start-filtered" ${!results.length?'disabled':''}>${state.settings.sessionSize} Fragen üben ${icon('arrow-right')}</button></div></div>${results.length?`<h2>Fragen entdecken</h2><div class="card">${results.slice(0,40).map(q=>`<button class="history-button" data-question="${q.id}"><div class="row"><span class="pill">#${q.id}</span><span class="tiny muted">${progress(q).mastered?'Sicher gelernt':progress(q).seen?'Schon geübt':'Neu'} ${state.bookmarks.includes(q.id)?icon('bookmark'):''}</span></div><p>${esc(q.text)}</p><small>${esc(q.topic)}</small></button>`).join('')}${results.length>40?'<p class="tiny muted">Die ersten 40 Treffer. Verfeinere deine Suche für weitere Fragen.</p>':''}</div>`:empty('Noch keine passenden Fragen',catalog.length?'Ändere die Filter oder wähle andere Module.':'Lade zuerst den Fragenkatalog unter Übersicht.')}`;}
function exam(){if(!catalog.length)return downloadIntro();return `<span class="eyebrow">DEINE GENERALPROBE</span><h1>Teste dein Können.</h1><p class="muted">Konzentriert üben. Ehrlich auswerten.</p>${moduleChips()}<div class="card"><h2>Prüfungssimulation</h2><div class="list-row row"><span>Fragen</span><strong>20 Hauptfragen je Modul</strong></div><div class="list-row row"><span>Zusatzfragen</span><strong>Nach richtiger Hauptfrage</strong></div><div class="list-row row"><span>Zeitlimit</span><strong>30 Minuten je Modul</strong></div><div class="list-row row"><span>Übungsziel</span><strong>80 % der Punkte je Modul</strong></div><p class="notice">Übungssimulation mit zufälliger Fragenauswahl. Keine amtliche Prüfungssoftware: Themenverteilung und Sonderregeln einzelner Klassen, insbesondere AM und Fahrlehrer, können abweichen.</p><p class="muted">Die Uhr läuft auch im Hintergrund weiter. Lösungen siehst du nach dem Abschluss. Deine Module werden nacheinander geprüft.</p><button class="primary full" data-action="start-exam" ${!currentPool().length?'disabled':''}>Simulation starten ${icon('arrow-right')}</button></div><div class="card"><h3>Grundwissen mitlernen</h3><p class="muted">Für den erstmaligen Erwerb der Klassen A–F gehört üblicherweise das Grundwissen dazu. Wähle die für dich erforderlichen Module mit deiner Fahrschule.</p></div>`;}
function startTrain(qs){if(!qs.length){toast('Für diese Auswahl sind keine Fragen vorhanden.');return;}if(state.active){toast('Bitte schließe zuerst deine laufende Einheit ab.');return;}const now=Date.now();state.active={id:now+'-'+Math.random().toString(36).slice(2,7),mode:'train',started:now,questions:qs,index:0,attempts:[],modules:[...state.settings.modules],selected:[],feedback:false,questionMs:0};selected=[];feedback=false;paused=false;tickMs=0;tickStart=performance.now();route='session';save();render();window.scrollTo(0,0);}
function startExam(){if(state.active){toast('Bitte schließe zuerst deine laufende Einheit ab.');return;}try{const modules=C.makeExam(catalog,state.settings.modules);const now=Date.now();state.active={id:now+'-'+Math.random().toString(36).slice(2,7),mode:'exam',started:now,modules,moduleIndex:0,groupIndex:0,part:'main',attempts:[],moduleStarted:now,deadline:now+modules[0].limitMs,questionMs:0,selected:[],feedback:false};selected=[];feedback=false;paused=false;tickMs=0;tickStart=performance.now();route='session';save();render();window.scrollTo(0,0);}catch(e){toast(e.message);}}
function question(){const a=state.active;if(!a)return null;if(a.mode==='train')return a.questions[a.index];const group=a.modules[a.moduleIndex].groups[a.groupIndex];return group[a.part];}
function activeTime(){if(tickStart&&!paused&&!feedback){tickMs+=Math.max(0,performance.now()-tickStart);tickStart=performance.now();}return tickMs;}
function checkpoint(){if(!state.active)return;state.active.questionMs=activeTime();state.active.selected=selected;state.active.feedback=feedback;save();}
function session(){const a=state.active;if(!a)return empty('Keine laufende Einheit','Starte eine Lernrunde.');const q=question(),isExam=a.mode==='exam';if(!q)return '';if(paused&&!isExam)return `<div class="card paused"><span class="empty-icon">${icon('pause')}</span><h1>Kurze Pause.</h1><p class="muted">Die aktive Lernzeit steht still.</p><button class="primary" data-action="continue">Weiterlernen ${icon('arrow-right')}</button><button class="text-btn full" data-action="abort">Einheit beenden</button></div>`;const label=isExam?`${C.classes[a.modules[a.moduleIndex].module]||'Modul'} · ${a.groupIndex+1} / 20`: `${a.index+1} / ${a.questions.length}`;return `<div class="row"><button class="text-btn" data-action="abort">${icon('arrow-left')} Beenden</button><span class="pill">${isExam?'Simulation':'Lernrunde'}</span><span class="timer" id="timer">${isExam?duration(Math.max(0,a.deadline-Date.now())):duration(activeTime())}</span></div><progress max="${isExam?20:a.questions.length}" value="${isExam?a.groupIndex:a.index}"></progress><div class="row" style="margin-top:20px"><small>${esc(label)} · ${q.points} Punkte</small><button class="text-btn" data-action="bookmark" aria-label="Frage merken">${icon('bookmark')+(state.bookmarks.includes(q.id)?' Gemerkt':' Merken')}</button></div><p class="eyebrow">${esc(q.topic)} · #${q.id}${isExam&&a.part==='sub'?' · ZUSATZFRAGE':''}</p><h1 class="qtitle">${esc(q.text)}</h1>${q.image?`<img class="qimage" src="https://img.f-online.at/${q.image}.jpg" alt="Abbildung zu Frage ${q.id}" data-essential>`:''}<p class="tiny muted">Eine oder mehrere Antworten können richtig sein.</p>${q.answers.map((ans,i)=>{let cl=selected.includes(i)?' chosen':'';if(feedback){if(ans.correct)cl+=' correct';else if(selected.includes(i))cl+=' wrong';}return `<button class="answer${cl}" data-answer="${i}" aria-pressed="${selected.includes(i)}" ${feedback?'disabled':''}><span class="box">${selected.includes(i)?icon('check'):''}</span><span>${esc(ans.text)}${ans.image?`<img src="https://img.f-online.at/${ans.image}.jpg" alt="Abbildung zu Antwort ${i+1}" data-essential>`:''}${feedback?`<small style="display:block">${ans.correct?'Richtige Antwort':'Nicht richtig'}</small>`:''}</span></button>`;}).join('')}${feedback?`<div class="card ${a.attempts.at(-1)?.correct?'good':'bad'}"><h3>${a.attempts.at(-1)?.correct?'Richtig beantwortet!':'Noch nicht ganz.'}</h3><small>Alle richtigen Antworten müssen ausgewählt sein.</small></div><button class="primary full" data-action="next">${a.index+1===a.questions.length?'Lernrunde abschließen':'Nächste Frage '+icon('arrow-right')}</button>`:`<button class="primary full" id="submit" data-action="answer" ${!selected.length?'disabled':''}>${isExam?'Antwort abgeben '+icon('arrow-right'):'Antwort prüfen'}</button>`}${feedback&&!isExam?aiPanel(q):''}${!isExam?'<button class="text-btn full" data-action="pause">Pause machen</button>':''}<p class="tiny muted">${isExam?'Ergebnisse und Lösungen erscheinen nach dem Abschluss.':'Die aktive Antwortzeit zählt nur, solange du diese Frage bearbeitest.'}</p>`;}
function attachImageErrors(){document.querySelectorAll('[data-essential]').forEach(img=>{img.onerror=()=>{img.dataset.failed='1';const warning=document.createElement('p');warning.className='image-error';warning.textContent='Bild fehlt. Verbinde dich mit dem Internet und lade das Bild erneut, bevor du antwortest.';const b=document.createElement('button');b.className='text-btn';b.textContent='Bild erneut laden';b.onclick=()=>{warning.remove();delete img.dataset.failed;img.src=img.src;};warning.append(b);img.after(warning);const btn=$('#submit');if(btn)btn.disabled=true;};img.onload=()=>{delete img.dataset.failed;const btn=$('#submit');if(btn)btn.disabled=!selected.length||!!document.querySelector('[data-failed]');};});}
function record(q,choices,ms,skipped=false){const a=state.active;const correct=!skipped&&C.grade(q,choices);const attempt={id:q.id,version:q.version,text:q.text,topic:q.topic,classes:q.classes,answers:q.answers,image:q.image,selected:[...choices],correct,ms,at:Date.now(),points:q.points,sessionId:a.id,mode:a.mode,skipped};a.attempts.push(attempt);state.attempts.push(attempt);const k=q.id+':'+q.version;if(!skipped){const p=pmap.get(k)||{seen:false,streak:0,wrong:0};p.seen=true;p.streak=correct?p.streak+1:0;p.mastered=p.streak>=3;p.wrong+=correct?0:1;p.last=attempt;pmap.set(k,p);}return attempt;}
function answer(){const a=state.active;if(!a||feedback||!selected.length)return;if(a.mode==='exam'&&Date.now()>=a.deadline){expireModule();return;}const missing=[...document.querySelectorAll('[data-essential]')].some(img=>!img.complete||!img.naturalWidth);if(missing){toast('Bitte zuerst alle Bilder laden. Ohne Bild ist die Frage nicht zuverlässig beantwortbar.');return;}const q=question();const attempt=record(q,selected,Math.round(activeTime()));tickStart=0;if(bridge?.feedback&&state.settings.haptics)try{bridge.feedback(attempt.correct?'correct':'wrong');}catch(e){}if(a.mode==='train'){if(!attempt.correct&&a.attempts.filter(x=>x.id===q.id&&x.version===q.version).length===1){const insert=Math.min(a.index+4,a.questions.length);a.questions.splice(insert,0,q);}feedback=true;checkpoint();render();return;}const m=a.modules[a.moduleIndex];if(attempt.correct)m.earned+=q.points;if(a.part==='main'&&q.sub&&attempt.correct){a.part='sub';resetQuestion();return;}if(a.part==='main'&&q.sub&&!attempt.correct){const sub=m.groups[a.groupIndex].sub;record(sub,[],0,true);}advanceExam();}
function resetQuestion(){selected=[];feedback=false;tickMs=0;tickStart=performance.now();checkpoint();render();window.scrollTo(0,0);}
function next(){const a=state.active;if(!a||a.mode!=='train'||!feedback)return;a.index++;if(a.index>=a.questions.length)finish('finished');else resetQuestion();}
function advanceExam(){const a=state.active;a.groupIndex++;a.part='main';if(a.groupIndex>=20)endModule();else resetQuestion();}
function endModule(){const a=state.active;const m=a.modules[a.moduleIndex];m.elapsed=Math.min(m.limitMs,Date.now()-a.moduleStarted);delete m.groups;a.moduleIndex++;if(a.moduleIndex>=a.modules.length){finish('finished');return;}a.groupIndex=0;a.part='main';a.moduleStarted=Date.now();a.deadline=a.moduleStarted+a.modules[a.moduleIndex].limitMs;toast('Nächstes Modul: '+C.classes[a.modules[a.moduleIndex].module]);resetQuestion();}
function expireModule(){const a=state.active;if(!a||a.mode!=='exam')return;const m=a.modules[a.moduleIndex];for(let i=a.groupIndex;i<m.groups.length;i++){const g=m.groups[i];if(i!==a.groupIndex||a.part==='main')record(g.main,[],0,true);if(g.sub)record(g.sub,[],0,true);}toast('Zeit abgelaufen. Offene Fragen erhalten keine Punkte.');endModule();}
function finish(status,show=true){const a=state.active;if(!a)return;const ended=Date.now();const s={id:a.id,mode:a.mode,started:a.started,ended,status,attempts:a.attempts,modules:a.mode==='exam'?a.modules.map(m=>({module:m.module,max:m.max,earned:m.earned,elapsed:m.elapsed||Math.max(0,Math.min(m.limitMs,ended-a.moduleStarted))})):a.modules,catalogHash:meta.hash};state.sessions.push(s);state.active=null;selected=[];feedback=false;tickStart=0;tickMs=0;save();if(show){reviewId=s.id;route='review';render();window.scrollTo(0,0);}}
function resume(){if(!state.active)return;selected=state.active.selected||[];feedback=!!state.active.feedback;tickMs=state.active.questionMs||0;tickStart=performance.now();paused=false;route='session';if(state.active.mode==='exam'&&Date.now()>=state.active.deadline){expireModule();return;}render();}
function chart(days){const max=Math.max(1,...days.map(d=>d.n));return `<svg class="chart" viewBox="0 0 420 140" role="img" aria-label="Fragen pro Tag in den letzten 14 Tagen"><line x1="5" y1="113" x2="415" y2="113" stroke="var(--line)"/>${days.map((d,i)=>`<rect x="${i*30+7}" y="${113-d.n/max*94}" width="18" height="${Math.max(2,d.n/max*94)}" rx="4" fill="var(--accent)" opacity="${i===13?1:.45}"><title>${esc(d.day)}: ${d.n} Fragen, ${d.correct} richtig</title></rect>${i%2===0||i===13?`<text x="${i*30+16}" y="133" text-anchor="middle">${d.day.slice(8)}</text>`:''}`).join('')}</svg>`;}
function stats(){let attempts=state.attempts.filter(a=>(!statPeriod||a.at>=Date.now()-statPeriod*86400000)&&(!statModule||a.classes.includes(statModule)));let sessions=state.sessions.filter(s=>(!statPeriod||s.started>=Date.now()-statPeriod*86400000)&&(!statModule||s.modules.some(m=>(m.module||m)===statModule)));const qs=catalog.filter(q=>!statModule||q.classes.includes(statModule)),s=C.stats(attempts,sessions,qs);const weak=Object.entries(s.topics).filter(([k,t])=>t.n>=3).sort((a,b)=>a[1].correct/a[1].n-b[1].correct/b[1].n).slice(0,6);return `<span class="eyebrow">DEIN FORTSCHRITT IN ZAHLEN</span><h1>Jede Frage zählt.</h1><p class="muted">Erkenne deine Stärken. Finde deine nächste Lernchance.</p><div class="card"><span class="eyebrow">Zeitraum</span><div class="chips" role="group" aria-label="Zeitraum">${[[0,'Gesamte Zeit'],[7,'7 Tage'],[30,'30 Tage'],[90,'90 Tage']].map(([n,l])=>`<button data-period="${n}" class="${statPeriod===n?'selected':''}" aria-pressed="${statPeriod===n}">${l}</button>`).join('')}</div><span class="eyebrow">Führerscheinklasse</span><div class="chips" role="group" aria-label="Modul">${[[0,'Alle Module'],...Object.entries(C.classes)].map(([n,l])=>`<button data-stat-module="${n}" class="${statModule===+n?'selected':''}" aria-pressed="${statModule===+n}">${esc(l)}</button>`).join('')}</div></div><div class="grid stats-grid" style="margin-top:18px">${stat(fmt(s.count),'Beantwortete Fragen','▤')}${stat(pct(s.accuracy),'Trefferquote','✓')}${stat(fmt(s.qpm,1),'Fragen / aktive Minute','◷')}${stat(fmt(s.totalMs/60000,1)+' min','Aktive Antwortzeit','◴')}</div><div class="card"><div class="row"><h2>Dein Lernrhythmus</h2><span class="pill">14 Tage</span></div>${chart(s.daily)}<div class="legend">${s.daily.map(d=>`<span>${d.day.slice(8)}.${d.day.slice(5,7)}: ${d.n}</span>`).join('')}</div></div><div class="grid stats-grid">${stat(s.avg==null?'–':fmt(s.avg/1000,1)+' s','Ø Antwortzeit','↔')}${stat(s.median==null?'–':fmt(s.median/1000,1)+' s','Median der Antwortzeit','◉')}${stat(s.p90==null?'–':fmt(s.p90/1000,1)+' s','90. Perzentil Antwortzeit','↗')}${stat(pct(s.firstAccuracy),'Beim ersten Versuch richtig','✧')}</div><div class="card"><h2>Katalog & Lernstand</h2><div class="list-row row"><span>Bearbeitete aktuelle Fragenversionen</span><strong>${s.seen} / ${qs.length}</strong></div><div class="list-row row"><span>Abdeckung</span><strong>${pct(s.coverage)}</strong></div><div class="list-row row"><span>Dreimal in Folge richtig</span><strong>${s.mastered}</strong></div><div class="list-row row"><span>Lernserie im Zeitraum</span><strong>${s.streak} Tage</strong></div><p class="tiny muted">Bei geändertem Fragetext oder Antwortschlüssel beginnt die Beherrschung dieser Frage neu. Historische Antworten bleiben erhalten. Zeitraumfilter gelten auch für diese Werte.</p></div><div class="card"><h2>Deine Prüfungssimulationen</h2><div class="row"><div class="stat"><strong>${s.passed} / ${s.exams}</strong><small>Übungsziel in allen Modulen erreicht</small></div><span class="pill">${s.exams?pct(s.passed/s.exams):'Noch offen'}</span></div><p class="tiny muted">Nur abgeschlossene Simulationen zählen zur Quote. Abgebrochene Einheiten bleiben im Verlauf sichtbar. Ein Modulfilter wählt Simulationen mit diesem Modul; das Gesamtbestehen berücksichtigt weiterhin alle ihre Module.</p></div><div class="card"><h2>Hier lohnt sich Wiederholen</h2>${weak.length?weak.map(([t,n])=>`<div class="list-row"><div class="row"><span>${esc(t)}</span><strong>${pct(n.correct/n.n)}</strong></div><small>${n.n} Antworten · ${fmt(n.ms/n.n/1000,1)} s im Schnitt</small><progress max="${n.n}" value="${n.correct}"></progress></div>`).join(''):'<p class="muted">Nach mindestens drei Antworten pro Thema erscheinen hier deine Schwachstellen.</p>'}</div><details class="card"><summary>So werden deine Werte berechnet</summary><p>Trefferquote: vollständig richtige Antworten geteilt durch abgegebene Antworten. Übersprungene Zusatzfragen und Zeitüberschreitungen zählen im Prüfungsergebnis als null Punkte, aber nicht als abgegebene Antworten.</p><p>Fragen pro Minute: abgegebene Antworten geteilt durch aktive Antwortzeit. Pausen, Hintergrundzeit und die Lösungsanzeige sind ausgeschlossen. Das Prüfungslimit verwendet dagegen die tatsächliche verstrichene Zeit.</p><p>Der Median ist die mittlere Antwortzeit. 90 % deiner Antworten waren höchstens so langsam wie das 90. Perzentil. Die Erstversuchsquote bezieht sich auf die erste Antwort zur aktuellen Fragenversion im gewählten Zeitraum.</p></details>`;}
function history(){const rows=state.sessions.filter(s=>historyFilter==='all'||s.mode===historyFilter).slice().reverse();return `<span class="eyebrow">DEIN LERNTAGEBUCH</span><h1>Deine bisherigen Etappen.</h1><div class="chips">${[['all','Alle'],['train','Lernrunden'],['exam','Simulationen']].map(([f,l])=>`<button data-history-filter="${f}" class="${historyFilter===f?'selected':''}">${l}</button>`).join('')}</div>${!rows.length?empty('Dein Verlauf beginnt hier','Jede abgeschlossene oder beendete Einheit wird hier lokal gespeichert.'):`<div class="card">${rows.slice(0,historyLimit).map(s=>{const as=s.attempts.filter(a=>!a.skipped),correct=as.filter(a=>a.correct).length;const result=s.mode==='exam'?s.modules.every(m=>m.earned>=m.max*.8):null;return `<button class="history-button" data-review="${esc(s.id)}"><div class="row"><h3>${s.mode==='exam'?'Prüfungssimulation':'Lernrunde'}</h3><span class="pill ${s.status==='aborted'?'':result===false?'bad':'good'}">${s.status==='aborted'?'Beendet':s.mode==='exam'?result?'Ziel erreicht':'Unter 80 %':pct(as.length?correct/as.length:null)}</span></div><small>${date(s.started)} · ${as.length} Antworten · ${duration(s.ended-s.started)}</small><p class="tiny muted">${s.modules.map(m=>esc(C.classes[m.module||m]||m)).join(' · ')}</p></button>`;}).join('')}${rows.length>historyLimit?'<button class="text-btn full" data-action="more-history">Weitere anzeigen</button>':''}</div>`}`;}
function review(){const s=state.sessions.find(s=>s.id===reviewId);if(!s)return empty('Einheit nicht gefunden','Öffne den Verlauf.');const as=s.attempts.filter(a=>!a.skipped),correct=as.filter(a=>a.correct).length;return `<button class="text-btn" data-route="history">${icon('arrow-left')} Zum Verlauf</button><span class="eyebrow" style="display:block">${s.mode==='exam'?'DEINE SIMULATION':'DEINE LERNRUNDE'}</span><h1>${s.status==='aborted'?'Einheit beendet.':'Etappe geschafft.'}</h1><p class="muted">${date(s.started)} · ${duration(s.ended-s.started)} verstrichen</p><div class="card center"><div class="score">${as.length?fmt(correct/as.length*100):'–'}<span style="font-size:25px"> %</span></div><p class="muted">${correct} von ${as.length} abgegebenen Antworten richtig</p>${s.mode==='exam'?s.modules.map(m=>`<div class="list-row row"><span>${C.classes[m.module]||'Modul '+m.module}</span><strong>${fmt(m.earned)} / ${fmt(m.max)} Punkte · ${pct(m.max?m.earned/m.max:0)}</strong></div>`).join(''):''}${s.status==='aborted'?'<p class="notice">Vorzeitig beendet. Diese Einheit zählt nicht als abgeschlossene Prüfung.</p>':''}</div><h2>Antworten nachsehen <span class="history-count">${s.attempts.length}</span></h2><p class="tiny muted">Die Lösungen zeigen die Fragenversion zum Zeitpunkt dieser Einheit.</p>${s.attempts.map(a=>`<details class="card"><summary><span class="pill ${a.skipped?'':a.correct?'good':'bad'}">${a.skipped?'Nicht beantwortet':a.correct?'Richtig':'Falsch'}</span> #${a.id} · ${esc(a.text)}</summary>${a.image?`<img class="qimage" src="https://img.f-online.at/${a.image}.jpg" alt="Frage ${a.id}">`:''}${a.answers.map((ans,i)=>`<div class="answer ${ans.correct?'correct':a.selected.includes(i)?'wrong':''}"><span>${a.selected.includes(i)?icon('square-check'):icon('square')}</span><span>${esc(ans.text)}${ans.correct?icon('check'):''}</span></div>`).join('')}<small>${a.skipped?'Keine Antwort abgegeben.':duration(a.ms)+' aktive Antwortzeit'}</small>${aiPanel(a)}</details>`).join('')}`;}
function settings(){return `<span class="eyebrow">DEIN LERNBEREICH</span><h1>So passt es zu dir.</h1>${aiSettings()}${updateCard()}<div class="card"><h2>Meine Module</h2>${moduleChips()}<p class="tiny muted">A1/A2 lernen mit Modul A. Unterklassen werden hier nicht als eigene Kataloge ausgewiesen. BE bleibt deaktiviert, solange die Quelle keinen separaten BE-Fragensatz liefert.</p><label for="goal">Tagesziel (Fragen)</label><input id="goal" type="number" min="1" max="1000" value="${state.settings.goal}"><label class="checkline"><input id="dark" type="checkbox" ${state.settings.dark?'checked':''}> Dunkles Design</label><label class="checkline"><input id="auto" type="checkbox" ${state.settings.auto?'checked':''}> Automatisch beim Öffnen prüfen (höchstens täglich)</label></div>${sourceCard()}<div class="card"><h2>Auch ohne Internet lernen</h2><p class="muted">Fragetexte und Antworten bleiben gespeichert. Bilder werden beim Ansehen lokal gespeichert. Lade die Bilder deiner gewählten Module vor einer Offline-Lernrunde herunter.</p><button class="secondary full" data-action="images" ${!catalog.length||transferBusy?'disabled':''}>${icon('download')} Bilder meiner Module herunterladen</button><p class="tiny muted">Der erste Bilddownload kann einige Minuten dauern. Lass die App geöffnet. Fehlende Bilder werden beim nächsten Download erneut versucht.</p></div><div class="card"><h2>Deine Daten gehören dir</h2><p class="muted">Ohne Konto, Werbung oder Analyse-Tracking. Lernstände und Verlauf bleiben auf diesem Gerät. Sichere sie vor einem Gerätewechsel oder einer Neuinstallation.</p><button class="secondary full" data-action="export">Sicherung als JSON exportieren</button><button class="text-btn full" data-action="import">Sicherung wiederherstellen</button><button class="text-btn full danger" data-action="reset">Lernfortschritt löschen</button></div><details class="card"><summary>Quelle & Hinweise</summary><p>Unabhängige Lern-App. Nicht mit F-Online oder einer Behörde verbunden. Quelle: öffentlicher österreichischer Fragenkatalog von F-Online. Die Aktualitätsanzeige beschreibt den letzten erfolgreichen Abgleich mit dieser Website; sie bestätigt keinen amtlichen Fragenstand.</p><p>F-Online behält sich Rechte an den Fragen und Bildern vor und verlangt in seinen AGB eine schriftliche Genehmigung zur Weiterverwendung. Kläre diese Genehmigung mit info@f-online.at, bevor du die Daten in dieser App verwendest oder weiterverbreitest.</p><p>Die APK enthält keine fremden Fragen oder Bilder. Downloads gehen direkt an F-Online; dabei erhält der Anbieter technisch deine IP-Adresse. Es werden keine Lernstatistiken übertragen.</p><button class="text-btn" data-action="source">Fragenquelle öffnen ${icon('external-link')}</button><p class="tiny muted">Fahrklar 1.0 · Österreich · Deutsch</p></details><details class="card"><summary>Open-Source-Lizenzen</summary><p>Piktogramme: Lucide. Frei verwendbar unter ISC-Lizenz; einzelne Formen stammen aus Feather (MIT).</p><pre class="license-text">${esc(Icons.license)}</pre></details>`;}
const actions={
 'ai-setup':()=>{if(bridge?.configureGemini)bridge.configureGemini();else toast('Die KI-Lernhilfe ist hier nicht verfügbar.');},
 'ai-remove':()=>{if(bridge?.deleteGeminiKey)bridge.deleteGeminiKey();},
 'ai-test':()=>{if(!bridge?.testGemini){toast('Der Verbindungstest ist hier nicht verfügbar.');return;}if(aiTest.phase==='loading')return;aiTest={phase:'loading',message:'Gemini Flash wird kontaktiert …'};render();try{bridge.testGemini();}catch(e){aiTest={phase:'error',message:'Verbindungstest konnte nicht gestartet werden.'};render();}},
 sync:async()=>{if(transferBusy)return;if(!bridge?.syncCatalog){toast('Der Katalogdownload ist hier nicht verfügbar.');return;}if(!state.settings.sourceEnabled){if(!await ask('F-Online verlangt eine schriftliche Genehmigung für die Weiterverwendung der Fragen und Bilder. Wenn diese für deine Nutzung vorliegt, kannst du den direkten Download aktivieren. Lernstatistiken bleiben auf deinem Gerät.','Download aktivieren'))return;state.settings.sourceEnabled=true;save();}transferBusy=true;downloadState={phase:'loading',message:''};render();bridge.syncCatalog();},
 quick:()=>startTrain(C.learningQueue(currentPool(),state.attempts,state.settings.sessionSize)),
 topics:topicPicker,
 'review-due':()=>{const qs=currentPool().filter(q=>C.reviewStatus(progress(q)).due);startTrain(C.learningQueue(qs,state.attempts,state.settings.sessionSize));},
 'check-update':()=>{if(!bridge?.checkUpdate){toast('Aktualisierungen sind hier nicht verfügbar.');return;}updateState={phase:'loading',message:web?'Web-App wird aktualisiert …':'GitHub wird nach einer neueren Version geprüft …',available:false};render();bridge.checkUpdate();},
 'open-update':()=>{if(bridge?.openUpdate)bridge.openUpdate();},
 weak:()=>{filter='wrong';route='learn';render();},
 'start-filtered':()=>{const qs=currentPool().filter(q=>(!topic||q.topic===topic)&&(!search||(q.text+' '+q.id+' '+q.answers.map(a=>a.text).join(' ')).toLowerCase().includes(search.toLowerCase()))&&(filter==='all'||filter==='due'&&C.reviewStatus(progress(q)).due||filter==='new'&&!progress(q).seen||filter==='wrong'&&progress(q).last&&!progress(q).last.correct||filter==='bookmarked'&&state.bookmarks.includes(q.id)||filter==='mastered'&&progress(q).mastered));startTrain(C.learningQueue(qs,state.attempts,state.settings.sessionSize));},
 'start-exam':startExam,answer,next,resume,
 bookmark:()=>{const q=question();state.bookmarks=state.bookmarks.includes(q.id)?state.bookmarks.filter(id=>id!==q.id):[...state.bookmarks,q.id];save();render();},
 pause:()=>{activeTime();paused=true;tickStart=0;checkpoint();render();},
 continue:()=>{paused=false;tickStart=performance.now();render();},
 abort:async()=>{if(await ask('Einheit beenden? Bisherige Antworten bleiben gespeichert.','Beenden'))finish('aborted');},
 export:()=>{checkpoint();const backup={...state,active:null};if(bridge?.exportState)bridge.exportState(JSON.stringify(backup,null,2));else toast('Export ist hier nicht verfügbar.');},
 import:()=>{if(bridge?.importState)bridge.importState();else toast('Import ist hier nicht verfügbar.');},
 reset:async()=>{if(await ask('Alle Antworten, Lernstände, Merkliste und Einheiten auf diesem Gerät löschen? Exportiere vorher eine Sicherung.','Löschen')){state.attempts=[];state.sessions=[];state.bookmarks=[];state.active=null;rebuildProgress();save();render();}},
 source:()=>{if(bridge?.openSource)bridge.openSource();},
 images:()=>{if(bridge?.cacheImages&&!transferBusy){transferBusy=true;render();toast('Bilder werden heruntergeladen …',true);bridge.cacheImages(JSON.stringify(state.settings.modules));}},
 'more-history':()=>{historyLimit+=30;render();}
};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.aiKey){requestAi(b.dataset.aiKey);return;}
 if(b.dataset.theme){if(['green','blue','purple','orange'].includes(b.dataset.theme)){state.settings.theme=b.dataset.theme;save();render();}return;}
 if(b.dataset.sessionSize){const size=+b.dataset.sessionSize;if([10,20,30].includes(size)){state.settings.sessionSize=size;save();render();}return;}
 if(b.dataset.period!=null){statPeriod=+b.dataset.period;render();return;}
 if(b.dataset.statModule!=null){statModule=+b.dataset.statModule;render();return;}
 if(b.dataset.route){go(b.dataset.route);return;}
 if(b.dataset.action){actions[b.dataset.action]?.();return;}
 if(b.dataset.module){const id=+b.dataset.module;let modules=[...state.settings.modules];if(modules.includes(id)){if(modules.length===1){toast('Wähle mindestens ein Modul.');return;}modules=modules.filter(n=>n!==id);}else modules.push(id);state.settings.modules=modules;topic='';save();render();return;}
 if(b.dataset.filter){filter=b.dataset.filter;render();return;}
 if(b.dataset.historyFilter){historyFilter=b.dataset.historyFilter;render();return;}
 if(b.dataset.review){reviewId=b.dataset.review;route='review';render();window.scrollTo(0,0);return;}
 if(b.dataset.question){const q=catalog.find(q=>q.id===+b.dataset.question);if(q)startTrain([q]);return;}
 if(b.dataset.answer!=null&&!feedback){if(state.active?.mode==='exam'&&Date.now()>=state.active.deadline){expireModule();return;}const i=+b.dataset.answer;selected=selected.includes(i)?selected.filter(n=>n!==i):[...selected,i];b.classList.toggle('chosen',selected.includes(i));b.setAttribute('aria-pressed',selected.includes(i));b.querySelector('.box').innerHTML=selected.includes(i)?icon('check'):'';const submit=$('#submit');if(submit)submit.disabled=!selected.length||!!document.querySelector('[data-failed]');checkpoint();}
});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='goal'){state.settings.goal=Math.max(1,Math.min(1000,+t.value||30));save();render();}if(['dark','auto','largeText','reduceMotion','keepAwake','haptics'].includes(t.id)){state.settings[t.id]=t.checked;save();render();}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const field=$('#search');field.focus();field.setSelectionRange(pos,pos);},220);}});
window.nativeEvent=async(type,message)=>{
if(type==='ai-key'){aiReady=!!bridge?.hasGeminiKey?.();aiPending=null;aiTest={phase:'idle',message:''};aiCache.clear();if(route==='settings')render();else refreshAiPanels();toast(aiReady?'Gemini-Key gespeichert. Prüfe ihn jetzt in den Einstellungen.':'Gemini-Key entfernt.');return;}
if(type==='ai-key-error'){toast(message);return;}
if(type==='ai-test'||type==='ai-test-error'){aiTest={phase:type==='ai-test'?'success':'error',message:String(message)};if(route==='settings')render();else toast(message);return;}
if(type==='ai-result'||type==='ai-error'){try{const result=JSON.parse(message);if(!aiPending||result.id!==aiPending.id)return;const key=aiPending.key;aiPending=null;aiCache.set(key,type==='ai-result'?{text:String(result.text)}:{error:String(result.text)});while(aiCache.size>100)aiCache.delete(aiCache.keys().next().value);refreshAiPanels();}catch(e){if(aiPending){aiCache.set(aiPending.key,{error:'Die KI-Antwort konnte nicht gelesen werden.'});aiPending=null;refreshAiPanels();}}return;}
if(type==='app-update'||type==='app-update-error'){try{const result=type==='app-update'?JSON.parse(message):{available:false,message};updateState={phase:type==='app-update'?'ready':'error',...result};}catch(e){updateState={phase:'error',available:false,message:'Die Versionsantwort konnte nicht gelesen werden.'};}if(route==='settings')render();return;}if(type==='updated'){transferBusy=false;await loadCatalog();downloadState=catalog.length?{phase:'idle',message:''}:{phase:'error',message:'Der gespeicherte Katalog konnte nicht geöffnet werden.'};toast(message);if(route!=='session')render();}else if(type==='import'){try{const data=C.validateBackup(JSON.parse(message));if(await ask('Die Sicherung ersetzt deinen aktuellen Lernstand. Fortfahren?','Wiederherstellen')){state={...data,settings:{...data.settings,sourceEnabled:state.settings.sourceEnabled},bookmarks:Array.isArray(data.bookmarks)?data.bookmarks.filter(Number.isInteger):[]};rebuildProgress();save();route='home';render();toast('Sicherung wiederhergestellt.');}}catch(e){toast('Sicherung ungültig: '+e.message);}}else {if(type==='sync'){transferBusy=true;if(message.startsWith('Fragenkatalog'))downloadState={phase:'loading',message:''};}if(type==='error'||type==='done'){transferBusy=false;if(type==='error'&&downloadState.phase==='loading')downloadState={phase:'error',message};}if(route!=='session')render();toast(message,type==='sync');}};
window.goBack=()=>{const dialog=document.querySelector('dialog[open]');if(dialog){dialog.dispatchEvent(new Event('cancel',{cancelable:true}));return true;}if(route==='home')return false;go('home');return true;};
window.pauseApp=()=>{activeTime();tickStart=0;paused=true;checkpoint();};
window.resumeApp=()=>{if(!state.active)return;if(state.active.mode==='exam'){paused=false;tickStart=performance.now();if(Date.now()>=state.active.deadline)expireModule();}else if(route==='session'){paused=true;render();}};
document.addEventListener('visibilitychange',()=>{if(document.hidden)window.pauseApp();else window.resumeApp();});
setInterval(()=>{if(!state.active)return;if(state.active.mode==='exam'&&Date.now()>=state.active.deadline){expireModule();return;}const timer=$('#timer');if(timer)timer.textContent=state.active.mode==='exam'?duration(Math.max(0,state.active.deadline-Date.now())):duration(activeTime());},500);
setInterval(()=>{if(state.active&&!document.hidden)checkpoint();},5000);
(async()=>{await loadCatalog();render();if(bridge?.syncCatalog&&state.settings.sourceEnabled&&state.settings.auto&&Date.now()-(meta.checkedAt||0)>86400000)bridge.syncCatalog();})();
function gameMetrics(qs){const answered=state.attempts.filter(a=>!a.skipped),correct=answered.filter(a=>a.correct).length,mastered=qs.filter(q=>progress(q).mastered).length,passed=state.sessions.filter(x=>x.mode==='exam'&&x.status==='finished'&&x.modules.every(m=>m.earned>=m.max*.8)).length,xp=correct*10+mastered*20+passed*100,today=C.dayKey(Date.now()),mistakes=answered.filter(a=>C.dayKey(a.at)===today&&!a.correct).length;return {xp,level:Math.floor(xp/500)+1,levelXp:xp%500,hearts:Math.max(0,5-Math.min(5,mistakes)),mastered,due:qs.filter(q=>C.reviewStatus(progress(q)).due).length};}
function playfulHome(){
 if(!catalog.length)return downloadIntro();
 const qs=currentPool(),s=C.stats(state.attempts,state.sessions,qs),g=gameMetrics(qs),remaining=Math.max(0,state.settings.goal-s.today);
 let html='<div class="game-status" aria-label="Dein heutiger Lernstatus"><div title="Lernserie">'+icon('flame')+'<strong>'+s.streak+'</strong><small>Tage</small></div><div title="Erfahrungspunkte">'+icon('sparkles')+'<strong>'+fmt(g.xp)+'</strong><small>XP</small></div><div title="Fokus-Herzen">'+icon('shield-check')+'<strong>'+g.hearts+'/5</strong><small>Fokus</small></div></div>';
 html+='<div class="row"><span class="eyebrow">DEIN LERNPFAD</span><span class="pill '+(saveFailed?'bad':'good')+'">'+(saveFailed?'Speicherfehler':icon('shield-check')+' lokal')+'</span></div><h1>Hallo, weiter geht’s!</h1><p class="muted">'+state.settings.modules.map(c=>esc(C.classes[c]||'Modul '+c)).join(' · ')+' · Eine kleine Etappe nach der anderen.</p>';
 html+='<section class="level-card"><div class="row"><div><span class="eyebrow">LEVEL '+g.level+'</span><h2>'+(g.levelXp<250?'Warmfahren':'Auf Erfolgskurs')+'</h2></div><strong>'+g.levelXp+' / 500 XP</strong></div><progress max="500" value="'+g.levelXp+'"></progress></section>';
 if(state.active)html+='<div class="card quest-card row"><div><span class="quest-icon">'+icon('pause')+'</span><h3>Deine Runde wartet</h3><small>Mach genau dort weiter.</small></div><button class="primary" data-action="resume">Weiter</button></div>';
 html+='<section class="daily-quest"><div class="row"><div><span class="eyebrow">TAGESAUFGABE</span><h2>'+(remaining?'Noch '+remaining+' Fragen':'Heute geschafft!')+'</h2></div><span class="xp-badge">+'+(remaining*10)+' XP möglich</span></div><progress max="'+state.settings.goal+'" value="'+Math.min(s.today,state.settings.goal)+'"></progress><small>'+s.today+' von '+state.settings.goal+' Fragen heute</small></section>';
 html+='<section class="learning-path" aria-label="Deine nächsten Lernetappen"><div class="path-line"></div><div class="path-stop left"><button class="path-node current" data-action="quick" aria-label="Adaptive Lernrunde starten">'+icon('book-open')+'</button><div><span class="pill">START</span><h3>Adaptive Lernrunde</h3><small>Neue und fällige Fragen</small></div></div><div class="path-stop right"><div><span class="pill">WIEDERHOLEN</span><h3>'+g.due+' Fragen fällig</h3><small>Fehler werden zuerst gefestigt</small></div><button class="path-node review" data-action="review-due" '+(!g.due?'disabled':'')+' aria-label="Fällige Fragen üben">'+icon('refresh-cw')+'</button></div><div class="path-stop left"><button class="path-node exam-node" data-route="exam" aria-label="Prüfungssimulation öffnen">'+icon('timer')+'</button><div><span class="pill">GENERALPROBE</span><h3>Prüfung simulieren</h3><small>20 Hauptfragen je Modul</small></div></div><div class="path-stop right"><div><span class="pill">MEISTERUNG</span><h3>'+g.mastered+' sicher gelernt</h3><small>Dreimal in Folge richtig</small></div><button class="path-node mastered" data-route="stats" aria-label="Fortschritt öffnen">'+icon('target')+'</button></div></section>';
 html+='<div class="grid stats-grid playful-stats">'+stat(fmt(s.today),'Heute','book-open')+stat(pct(s.accuracy),'Trefferquote','circle-check')+stat(fmt(s.qpm,1),'Fragen/Minute','timer')+stat(fmt(g.mastered),'Gemeistert','target')+'</div><div class="dashboard-grid"><div class="card"><h2>Deine nächste Belohnung</h2><p class="muted">Noch '+(500-g.levelXp)+' XP bis Level '+(g.level+1)+'. Jede vollständig richtige Antwort bringt 10 XP.</p><button class="secondary full" data-action="weak">Fehler gezielt üben '+icon('arrow-right')+'</button></div>'+sourceCard()+'</div><p class="tiny muted center">Fokus-Herzen zeigen deine heutigen Fehler, sperren aber keine Übungen. „Sicher gelernt“ ist eine Lernhilfe und keine Bestehensgarantie.</p>';
 return html;
}
